Object.assign(rows, landingRows);

const dictionary = new Map();
const phraseRows = new Map();
for (const [source, translations] of Object.entries(rows)) {
  phraseRows.set(source, translations);
  translations.forEach((phrase) => {
    if (!phraseRows.has(phrase)) phraseRows.set(phrase, translations);
  });
  languages.forEach((language, index) => {
    dictionary.set(`${language}:${source}`, translations[index]);
  });
}

export function translateText(text, language = 'en') {
  const exact = text.trim();
  const translated = phraseRows.get(exact)?.[languages.indexOf(language)];
  return translated ?? dictionary.get(`${language}:${exact}`) ?? text;
}

export function translatePage(language = 'en') {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const translated = translateText(node.nodeValue, language);
    if (translated !== node.nodeValue) node.nodeValue = node.nodeValue.replace(node.nodeValue.trim(), translated);
  }
  for (const element of document.querySelectorAll('[placeholder], [aria-label], [title]')) {
    for (const name of ['placeholder', 'aria-label', 'title']) {
      if (element.hasAttribute(name)) element.setAttribute(name, translateText(element.getAttribute(name), language));
    }
  }
}

export { languages };
